          if (currentView === 'chat' && activeRoomId) {
            await pollActiveRoomMessages();
            await pollBackgroundOtherRooms();
          } else if (currentView === 'lobby') {
            await pollLobbyUpdates();
          } else if (currentView === 'settings') {
            await pollBackgroundOtherRooms();
          }
